import { Injectable, InjectionToken, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Note {
  id: number;
  text: string;
}

export type NoteError =
  | { kind: "Empty" }
  | { kind: "NotFound"; value: number }
  | { kind: "Storage"; value: string };

/** Where the server is; empty for the page's own origin. */
export const API_BASE_URL = new InjectionToken<string>('API_BASE_URL', {
  providedIn: 'root',
  factory: () => '',
});

/**
 * The API functions of `notes`. A function that returns `Err` fails
 * with status 422 and the error as `HttpErrorResponse.error`.
 */
@Injectable({ providedIn: 'root' })
export class NotesClient {
  private readonly http = inject(HttpClient);
  private readonly base = inject(API_BASE_URL);

  listNotes(): Observable<Note[]> {
    return this.http.post<Note[]>(`${this.base}/api/list_notes`, {});
  }

  addNote(text: string): Observable<Note> {
    return this.http.post<Note>(`${this.base}/api/add_note`, { text });
  }

  deleteNote(id: number): Observable<boolean> {
    return this.http.post<boolean>(`${this.base}/api/delete_note`, { id });
  }
}
